# User explicitly requested the equivalent of curl -k for this Y transport.
# Keep this local to these GitHub clients, not Python's global HTTPS defaults.
def configure_y_github_tls():
    import ssl,urllib.request
    def initialize(self,token=None):
        self.token=token
        context=ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
        context.check_hostname=False
        context.verify_mode=ssl.CERT_NONE
        self.opener=urllib.request.build_opener(API.NoRedirect(),urllib.request.HTTPSHandler(context=context))
    API.GitHub.__init__=initialize
configure_y_github_tls()

